// Định dạng giờ theo múi Việt Nam, không phụ thuộc múi giờ của máy chạy Node-RED.
function phan_gio(d) {
    const p = {};
    new Intl.DateTimeFormat('en-GB', {
        timeZone: 'Asia/Ho_Chi_Minh', hourCycle: 'h23',
        year: 'numeric', month: '2-digit', day: '2-digit',
        hour: '2-digit', minute: '2-digit', second: '2-digit'
    }).formatToParts(new Date(d)).forEach(x => { p[x.type] = x.value; });
    return p;
}

const level = msg.payload && msg.payload.level;
// Chỉ nhận số thật; chuỗi hay null nghĩa là firmware hoặc cảm biến lỗi.
if (typeof level !== 'number' || !Number.isFinite(level)) {
    node.status({ fill: 'red', shape: 'ring', text: 'số đo không hợp lệ' });
    node.warn('feeder/level: level không phải số: ' + JSON.stringify(msg.payload));
    return null;
}
if (level < 0 || level > 100) {
    node.status({ fill: 'red', shape: 'ring', text: 'ngoài 0..100: ' + level });
    node.warn('feeder/level: level ngoài 0..100: ' + level);
    return null;
}
const muc = Math.round(level);
const ts = Date.now();
// ID 6 và các tab khác đọc mức mới nhất từ đây, không cần đợi Supabase.
global.set('muc_moi_nhat', { level: muc, ts });

const p = phan_gio(ts);
const gio = p.hour + ':' + p.minute + ':' + p.second;
node.status({ fill: 'green', shape: 'dot', text: muc + ' % lúc ' + gio });

const hop_le = { payload: { level: muc, distance_cm: msg.payload.distance_cm }, topic: 'feeder/level' };
return [{ payload: muc }, { payload: gio }, hop_le];

// Đọc cấu hình Supabase từ biến môi trường, không ghi key vào flow vì repo public.
const url = env.get('SUPABASE_URL');
const key = env.get('SUPABASE_KEY');
if (!url || !key) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'chưa cấu hình Supabase' });
    return null;
}

// ESP32 gửi 5 s/lần; ID 4 của Quân chỉ đọc tối đa 1000 dòng/24h,
// 2 phút/lần = 720 dòng/ngày nên biểu đồ 24 giờ vẫn đủ dữ liệu.
const KHOANG_GHI_MS = 120 * 1000;
const bay_gio = Date.now();
const lan_ghi_cuoi = flow.get('lan_ghi_cuoi') || 0;
if (bay_gio - lan_ghi_cuoi < KHOANG_GHI_MS) return null;
flow.set('lan_ghi_cuoi', bay_gio);

return {
    loai_ghi: 'level',
    method: 'POST',
    url: url + '/rest/v1/feeder_events',
    headers: {
        apikey: key,
        Authorization: 'Bearer ' + key,
        'Content-Type': 'application/json',
        Prefer: 'return=minimal'
    },
    payload: JSON.stringify({ event: 'level', level: msg.payload.level })
};

// Chỉ ghi khi cửa đã đóng xong; opening/rejected không phải một lần cho ăn.
const s = msg.payload;
if (!s || s.event !== 'feed' || s.result !== 'done') return null;

const thoi_gian = s.duration_ms;
if (typeof thoi_gian !== 'number' || !Number.isFinite(thoi_gian) || thoi_gian <= 0) {
    node.status({ fill: 'red', shape: 'ring', text: 'duration_ms sai' });
    node.warn('feeder/status: duration_ms không hợp lệ: ' + JSON.stringify(s));
    return null;
}
// Đọc cấu hình Supabase từ biến môi trường, không ghi key vào flow vì repo public.
const url = env.get('SUPABASE_URL');
const key = env.get('SUPABASE_KEY');
if (!url || !key) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'chưa cấu hình Supabase' });
    return null;
}
node.status({});
return {
    loai_ghi: 'feed',
    method: 'POST',
    url: url + '/rest/v1/feeder_events',
    headers: {
        apikey: key,
        Authorization: 'Bearer ' + key,
        'Content-Type': 'application/json',
        Prefer: 'return=minimal'
    },
    payload: JSON.stringify({ event: 'feed', duration_ms: Math.round(thoi_gian) })
};

// Định dạng giờ theo múi Việt Nam, không phụ thuộc múi giờ của máy chạy Node-RED.
function phan_gio(d) {
    const p = {};
    new Intl.DateTimeFormat('en-GB', {
        timeZone: 'Asia/Ho_Chi_Minh', hourCycle: 'h23',
        year: 'numeric', month: '2-digit', day: '2-digit',
        hour: '2-digit', minute: '2-digit', second: '2-digit'
    }).formatToParts(new Date(d)).forEach(x => { p[x.type] = x.value; });
    return p;
}

// Supabase trả 201 khi chèn thành công (Prefer: return=minimal nên body rỗng).
if (msg.statusCode === 201) {
    const p = phan_gio(Date.now());
    node.status({ fill: 'green', shape: 'dot', text: 'đã ghi ' + p.hour + ':' + p.minute });
    // Ghi xong thì làm mới bảng lịch sử ngay.
    return { payload: 'sau_khi_ghi' };
}
// Ghi mức lỗi thì bỏ mốc thời gian để số đo kế tiếp thử ghi lại, không phải đợi 2 phút.
if (msg.loai_ghi === 'level') flow.set('lan_ghi_cuoi', 0);
node.status({ fill: 'red', shape: 'ring', text: 'lỗi ' + (msg.statusCode || 'mạng') });
node.warn('Ghi Supabase (' + msg.loai_ghi + ') thất bại: ' + (msg.statusCode || 'lỗi mạng') + ' ' + (msg.payload || ''));
return null;

// Đọc cấu hình Supabase từ biến môi trường, không ghi key vào flow vì repo public.
const url = env.get('SUPABASE_URL');
const key = env.get('SUPABASE_KEY');
if (!url || !key) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'chưa cấu hình Supabase' });
    return null;
}

const q = 'select=created_at,event,level,duration_ms&order=created_at.desc&limit=10';
return {
    method: 'GET',
    url: url + '/rest/v1/feeder_events?' + q,
    headers: { apikey: key, Authorization: 'Bearer ' + key },
    payload: null
};

// Định dạng giờ theo múi Việt Nam, không phụ thuộc múi giờ của máy chạy Node-RED.
function phan_gio(d) {
    const p = {};
    new Intl.DateTimeFormat('en-GB', {
        timeZone: 'Asia/Ho_Chi_Minh', hourCycle: 'h23',
        year: 'numeric', month: '2-digit', day: '2-digit',
        hour: '2-digit', minute: '2-digit', second: '2-digit'
    }).formatToParts(new Date(d)).forEach(x => { p[x.type] = x.value; });
    return p;
}

if (msg.statusCode !== 200 || !Array.isArray(msg.payload)) {
    // Giữ nguyên bảng cũ thay vì xóa trắng khi mất mạng.
    node.status({ fill: 'red', shape: 'ring', text: 'lỗi ' + (msg.statusCode || 'dữ liệu') });
    node.warn('Đọc lịch sử Supabase thất bại: ' + (msg.statusCode || 'dữ liệu sai'));
    return null;
}
const dong = msg.payload.map(r => {
    const p = phan_gio(r.created_at);
    const la_muc = r.event === 'level';
    return {
        thoi_gian: p.day + '/' + p.month + ' ' + p.hour + ':' + p.minute,
        su_kien: la_muc ? 'Đo mức' : 'Cho ăn',
        gia_tri: la_muc ? r.level + ' %' : (r.duration_ms / 1000).toFixed(1) + ' s'
    };
});
node.status({ fill: 'green', shape: 'dot', text: dong.length + ' dòng' });
return { payload: dong, action: 'replace' };

// Nút gửi thử bỏ qua công tắc để kiểm tra cấu hình bất cứ lúc nào.
const gui_thu = msg.payload === 'gui_thu';
if (!gui_thu && flow.get('email_bat') === false) {
    node.status({ fill: 'grey', shape: 'ring', text: 'công tắc tắt, không gửi' });
    return null;
}
if (!env.get('EMAIL_TO')) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'chưa đặt EMAIL_TO' });
    return null;
}
// Đọc cấu hình Supabase từ biến môi trường, không ghi key vào flow vì repo public.
const url = env.get('SUPABASE_URL');
const key = env.get('SUPABASE_KEY');
if (!url || !key) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'chưa cấu hình Supabase' });
    return null;
}
node.status({});
return {
    method: 'GET',
    url: url + '/rest/v1/feeder_events?select=created_at,level&event=eq.level&order=created_at.desc&limit=1',
    headers: { apikey: key, Authorization: 'Bearer ' + key },
    payload: null
};

if (msg.statusCode !== 200 || !Array.isArray(msg.payload)) {
    // Không có số liệu thật thì không gửi email để tránh báo sai.
    node.status({ fill: 'red', shape: 'ring', text: 'lỗi ' + (msg.statusCode || 'mạng') });
    node.warn('Email 20:00: đọc mức thất bại: ' + (msg.statusCode || 'lỗi mạng'));
    return null;
}
const url = env.get('SUPABASE_URL');
const key = env.get('SUPABASE_KEY');

// Nửa đêm hôm nay theo giờ Việt Nam, đổi ra UTC cho Supabase.
// Việt Nam cố định UTC+7, không có giờ mùa hè.
const ngay_vn = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Ho_Chi_Minh' });
const nua_dem = new Date(ngay_vn + 'T00:00:00+07:00').toISOString();
node.status({});
return {
    muc_moi_nhat: msg.payload[0] || null,
    method: 'GET',
    url: url + '/rest/v1/feeder_events?event=eq.feed&created_at=gte.' + encodeURIComponent(nua_dem)
        + '&select=created_at,duration_ms&order=created_at.asc',
    headers: { apikey: key, Authorization: 'Bearer ' + key },
    payload: null
};

// Định dạng giờ theo múi Việt Nam, không phụ thuộc múi giờ của máy chạy Node-RED.
function phan_gio(d) {
    const p = {};
    new Intl.DateTimeFormat('en-GB', {
        timeZone: 'Asia/Ho_Chi_Minh', hourCycle: 'h23',
        year: 'numeric', month: '2-digit', day: '2-digit',
        hour: '2-digit', minute: '2-digit', second: '2-digit'
    }).formatToParts(new Date(d)).forEach(x => { p[x.type] = x.value; });
    return p;
}

if (msg.statusCode !== 200 || !Array.isArray(msg.payload)) {
    node.status({ fill: 'red', shape: 'ring', text: 'lỗi ' + (msg.statusCode || 'mạng') });
    node.warn('Email 20:00: đọc lịch sử cho ăn thất bại: ' + (msg.statusCode || 'lỗi mạng'));
    return null;
}
const NGUONG = 20;   // cùng ngưỡng sắp hết với ID 5
const muc = msg.muc_moi_nhat;
const hom_nay = phan_gio(Date.now());
const feeds = msg.payload;

const dong = [];
if (muc) {
    const p = phan_gio(muc.created_at);
    dong.push('Mức thức ăn hiện tại: ' + muc.level + ' % (đo lúc ' + p.hour + ':' + p.minute + ').');
} else {
    dong.push('Mức thức ăn hiện tại: chưa có dữ liệu.');
}
dong.push('Số lần cho ăn hôm nay: ' + feeds.length + '.');
feeds.forEach((f, i) => {
    const p = phan_gio(f.created_at);
    dong.push('  ' + (i + 1) + '. ' + p.hour + ':' + p.minute + ' - mở cửa ' + (f.duration_ms / 1000).toFixed(1) + ' s');
});
if (muc && muc.level < NGUONG) {
    dong.push('');
    dong.push('CẢNH BÁO: thức ăn còn dưới ' + NGUONG + ' %, hãy châm thêm.');
}
dong.push('');
dong.push('Email tự động từ hộp cho thú cưng ăn (Node-RED).');

node.status({ fill: 'green', shape: 'dot', text: 'đã soạn, đang gửi' });
// Tạo msg mới: không mang msg.headers của Supabase (có key) sang node email.
return {
    to: env.get('EMAIL_TO'),
    topic: 'Báo cáo hộp cho ăn ngày ' + hom_nay.day + '/' + hom_nay.month + '/' + hom_nay.year,
    payload: dong.join('\n')
};

// Định dạng giờ theo múi Việt Nam, không phụ thuộc múi giờ của máy chạy Node-RED.
function phan_gio(d) {
    const p = {};
    new Intl.DateTimeFormat('en-GB', {
        timeZone: 'Asia/Ho_Chi_Minh', hourCycle: 'h23',
        year: 'numeric', month: '2-digit', day: '2-digit',
        hour: '2-digit', minute: '2-digit', second: '2-digit'
    }).formatToParts(new Date(d)).forEach(x => { p[x.type] = x.value; });
    return p;
}

// Node email không có đầu ra, nên đọc kết quả qua node status / catch.
if (msg.error) {
    node.status({ fill: 'red', shape: 'ring', text: 'gửi email thất bại' });
    node.warn('Gửi email thất bại: ' + (msg.error.message || msg.error));
    return null;
}
const s = msg.status || {};
if (s.fill === 'red') {
    node.status({ fill: 'red', shape: 'ring', text: 'gửi email thất bại' });
    return null;
}
// Gửi xong node email đặt status rỗng kèm phản hồi của máy chủ SMTP.
if (!s.fill && s.response) {
    const p = phan_gio(Date.now());
    node.status({ fill: 'green', shape: 'dot', text: 'đã gửi ' + p.hour + ':' + p.minute });
}
return null;

// Chỉ trả lời về đúng trình duyệt gửi form (msg._client), không thì sẽ phát cho mọi người.
const khach = msg._client;
if (!khach || !khach.socketId) {
    node.status({ fill: 'red', shape: 'dot', text: 'thiếu _client' });
    node.warn('Thiếu msg._client: bật "Include client data" ở ui-base');
    return null;
}
const tra_loi = (chu) => ({ _client: khach, payload: chu });

const vao = msg.payload || {};
const ten = String(vao.ten_dang_nhap || '').trim();
const mat_khau = String(vao.mat_khau || '');
if (!/^[A-Za-z0-9_]{3,32}$/.test(ten)) {
    return [null, tra_loi('Tên đăng nhập 3-32 ký tự, chỉ gồm chữ, số và dấu _')];
}
if (mat_khau.length < 6) {
    return [null, tra_loi('Mật khẩu phải có ít nhất 6 ký tự')];
}

// scrypt chạy bất đồng bộ để không chặn Node-RED. Mật khẩu gốc không đi tiếp sang node sau.
const muoi = crypto.randomBytes(16);
crypto.scrypt(mat_khau, muoi, 64, (loi, khoa) => {
    if (loi) {
        node.status({ fill: 'red', shape: 'dot', text: 'lỗi băm' });
        node.warn('Không băm được mật khẩu: ' + loi.message);
        node.send([null, tra_loi('Lỗi máy chủ, thử lại sau')]);
        node.done();
        return;
    }
    node.status({});
    node.send([{
        _client: khach,
        ten_dang_nhap: ten,
        // Truy vấn có tham số, không ghép chuỗi từ dữ liệu người dùng.
        params: { $ten: ten, $hash: khoa.toString('hex'), $muoi: muoi.toString('hex'), $luc: new Date().toISOString() }
    }, null]);
    node.done();
});
return null;

const khach = msg._client;
if (!khach || !khach.socketId) {
    node.status({ fill: 'red', shape: 'dot', text: 'thiếu _client' });
    node.warn('Thiếu msg._client: bật "Include client data" ở ui-base');
    return null;
}
const vao = msg.payload || {};
const ten = String(vao.ten_dang_nhap || '').trim();
const mat_khau = String(vao.mat_khau || '');
if (!ten || !mat_khau) {
    return [null, { _client: khach, payload: 'Nhập tên đăng nhập và mật khẩu' }];
}
// Mật khẩu phải đi qua node sqlite để so với hash; node sau xoá ngay, không ghi log.
return [{ _client: khach, ten_dang_nhap: ten, mat_khau_tam: mat_khau, params: { $ten: ten } }, null];

// Tên trang phải trùng tên ui-page (ui-control tìm trang theo tên).
const TRANG_CHINH = 'Dashboard';

const mat_khau = String(msg.mat_khau_tam || '');
delete msg.mat_khau_tam;
const khach = msg._client;
const dong = Array.isArray(msg.payload) ? msg.payload[0] : null;
const sai = { _client: khach, payload: 'Sai tên đăng nhập hoặc mật khẩu' };

// Không có user vẫn băm với muối giả để thời gian trả lời gần như nhau,
// tránh dò xem tên nào đã tồn tại.
const muoi = dong ? Buffer.from(dong.muoi, 'hex') : crypto.randomBytes(16);
crypto.scrypt(mat_khau, muoi, 64, (loi, khoa) => {
    if (loi) {
        node.status({ fill: 'red', shape: 'dot', text: 'lỗi băm' });
        node.warn('Không băm được mật khẩu: ' + loi.message);
        node.send([null, null, { _client: khach, payload: 'Lỗi máy chủ, thử lại sau' }]);
        node.done();
        return;
    }
    const luu = dong ? Buffer.from(dong.mat_khau_hash, 'hex') : null;
    // timingSafeEqual báo lỗi nếu khác độ dài nên kiểm tra trước.
    const dung = !!luu && luu.length === khoa.length && crypto.timingSafeEqual(luu, khoa);
    if (!dung) {
        node.send([null, null, sai]);
        node.done();
        return;
    }
    const phien = flow.get('phien') || {};
    phien[khach.socketId] = { ten: dong.ten_dang_nhap, luc: new Date().toISOString() };
    flow.set('phien', phien);
    node.status({ fill: 'green', shape: 'dot', text: Object.keys(phien).length + ' phiên' });
    node.send([
        { _client: khach, payload: { page: TRANG_CHINH } },
        { _client: khach, payload: { ten: dong.ten_dang_nhap } },
        { _client: khach, payload: 'Xin chào ' + dong.ten_dang_nhap }
    ]);
    node.done();
});
return null;

// Lỗi từ các node sqlite (node sqlite chỉ báo lỗi qua catch, không ra cổng output).
// Không ghi cả msg ra log vì msg đăng nhập có mật khẩu tạm.
delete msg.mat_khau_tam;
const SQL_THEM_ID = '7a1c000000007022';
const thong_bao = (msg.error && msg.error.message) || '';
const nguon = msg.error && msg.error.source && msg.error.source.id;
const khach = msg._client;

if (nguon === SQL_THEM_ID && thong_bao.includes('UNIQUE')) {
    return khach ? { _client: khach, payload: 'Tên đăng nhập đã có người dùng' } : null;
}
node.status({ fill: 'red', shape: 'dot', text: 'lỗi SQLite' });
node.warn('Lỗi SQLite: ' + thong_bao);
// Lỗi lúc tạo bảng không có _client: không gửi thông báo, nếu không sẽ hiện cho mọi người.
return khach ? { _client: khach, payload: 'Lỗi cơ sở dữ liệu, thử lại sau' } : null;

// ui-event gửi { topic: '$pageview', payload: { page: { id, name, path, ... }, query } }.
const TRANG_DANG_NHAP_ID = '7a1c000000007003';
const TRANG_DANG_NHAP = 'Đăng nhập';

if (msg.topic !== '$pageview') return null;
const socket_id = msg._client && msg._client.socketId;
if (!socket_id) return null;
const trang = (msg.payload && msg.payload.page) || {};
if (trang.id === TRANG_DANG_NHAP_ID) return null;

const phien = flow.get('phien') || {};
if (phien[socket_id]) return null;
// Chưa đăng nhập mà vào trang khác: chỉ chuyển trình duyệt này.
return { _client: msg._client, payload: { page: TRANG_DANG_NHAP } };

// ui-template gửi { hanh_dong: 'hoi_ten' } khi hiện ra, { hanh_dong: 'dang_xuat' } khi bấm nút.
const TRANG_DANG_NHAP = 'Đăng nhập';

const khach = msg._client;
const socket_id = khach && khach.socketId;
if (!socket_id) return null;
const hanh_dong = msg.payload && msg.payload.hanh_dong;
const phien = flow.get('phien') || {};

if (hanh_dong === 'hoi_ten') {
    const p = phien[socket_id];
    return [null, { _client: khach, payload: { ten: p ? p.ten : null } }];
}
if (hanh_dong === 'dang_xuat') {
    delete phien[socket_id];
    flow.set('phien', phien);
    node.status({ fill: 'grey', shape: 'ring', text: Object.keys(phien).length + ' phiên' });
    return [
        { _client: khach, payload: { page: TRANG_DANG_NHAP } },
        { _client: khach, payload: { ten: null } }
    ];
}
return null;

// ui-control (events = connect) gửi payload 'connect' / 'lost' kèm msg._client.socketId.
if (msg.payload !== 'lost') return null;
const socket_id = msg._client && msg._client.socketId;
if (!socket_id) return null;
const phien = flow.get('phien') || {};
if (phien[socket_id]) {
    delete phien[socket_id];
    flow.set('phien', phien);
}
node.status({ fill: 'grey', shape: 'ring', text: Object.keys(phien).length + ' phiên' });
return null;
